class Solution:
    def maxOperations(self, nums: List[int]) -> int:
        n = len(nums)
        def solve(t):
            dp = [[0] * n for _ in range(n)]
            for l in range(n - 2, -1, -1):
                for r in range(l + 1, n):
                    b = 0
                    if nums[l] + nums[l+1] == t and l + 2 <= r:
                        b = max(b, 1 + dp[l+2][r])
                    elif nums[l] + nums[l+1] == t:
                        b = max(b, 1)
                    if nums[r-1] + nums[r] == t and l <= r - 2:
                        b = max(b, 1 + dp[l][r-2])
                    elif nums[r-1] + nums[r] == t:
                        b = max(b, 1)
                    if nums[l] + nums[r] == t and l + 1 <= r - 1:
                        b = max(b, 1 + dp[l+1][r-1])
                    elif nums[l] + nums[r] == t:
                        b = max(b, 1)
                    dp[l][r] = b
            return dp[0][n-1]
        return max(solve(nums[0] + nums[1]), solve(nums[-1] + nums[-2]), solve(nums[0] + nums[-1]))

