class Solution {
public:
    int solve(vector<int>& a, int t) {
        int n = a.size();
        vector<vector<int>> dp(n, vector<int>(n, 0));
        for (int l = n - 2; l >= 0; l--)
            for (int r = l + 1; r < n; r++) {
                int b = 0;
                if (a[l] + a[l+1] == t) b = max(b, (l + 2 <= r ? 1 + dp[l+2][r] : 1));
                if (a[r-1] + a[r] == t) b = max(b, (l <= r - 2 ? 1 + dp[l][r-2] : 1));
                if (a[l] + a[r] == t) b = max(b, (l + 1 <= r - 1 ? 1 + dp[l+1][r-1] : 1));
                dp[l][r] = b;
            }
        return dp[0][n-1];
    }
    int maxOperations(vector<int>& nums) {
        return max({solve(nums, nums[0] + nums[1]), solve(nums, nums[nums.size()-1] + nums[nums.size()-2]), solve(nums, nums[0] + nums.back())});
    }
};

