class Solution {
    private int[] a;
    private int[][] dp;
    private int solve(int t) {
        int n = a.length;
        for (int l = n - 2; l >= 0; l--)
            for (int r = l + 1; r < n; r++) {
                int b = 0;
                if (a[l] + a[l+1] == t) b = Math.max(b, l + 2 <= r ? 1 + dp[l+2][r] : 1);
                if (a[r-1] + a[r] == t) b = Math.max(b, l <= r - 2 ? 1 + dp[l][r-2] : 1);
                if (a[l] + a[r] == t) b = Math.max(b, l + 1 <= r - 1 ? 1 + dp[l+1][r-1] : 1);
                dp[l][r] = b;
            }
        return dp[0][n-1];
    }
    public int maxOperations(int[] nums) {
        a = nums; int n = nums.length; dp = new int[n][n];
        return Math.max(solve(nums[0] + nums[1]), Math.max(solve(nums[n-1] + nums[n-2]), solve(nums[0] + nums[n-1])));
    }
}

