var maxOperations = function(nums) {
    const n = nums.length;
    const solve = (t) => {
        const dp = Array.from({length: n}, () => new Array(n).fill(0));
        for (let l = n - 2; l >= 0; l--)
            for (let r = l + 1; r < n; r++) {
                let b = 0;
                if (nums[l] + nums[l+1] === t) b = Math.max(b, l + 2 <= r ? 1 + dp[l+2][r] : 1);
                if (nums[r-1] + nums[r] === t) b = Math.max(b, l <= r - 2 ? 1 + dp[l][r-2] : 1);
                if (nums[l] + nums[r] === t) b = Math.max(b, l + 1 <= r - 1 ? 1 + dp[l+1][r-1] : 1);
                dp[l][r] = b;
            }
        return dp[0][n-1];
    };
    return Math.max(solve(nums[0] + nums[1]), solve(nums[n-1] + nums[n-2]), solve(nums[0] + nums[n-1]));
